field_code = #{model.fieldCode}, field_name = #{model.fieldName}, field_creator_id = #{model.fieldCreatorId}, field_create_time = #{model.fieldCreateTime}, field_updater_id = #{model.fieldUpdaterId}, field_update_time = #{model.fieldUpdateTime}, field_enable = #{model.fieldEnable},
WHERE field_id = #{model.fieldId}

