SELECT

FROM sys_org_role

    AND field_id = #{model.fieldId}
    AND field_code LIKE CONCAT('%', #{model.fieldCode}, '%')
    AND field_name LIKE CONCAT('%', #{model.fieldName}, '%')
    AND field_enable = #{model.fieldEnable}

ORDER BY field_create_time DESC


    LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT field_id, field_name
FROM sys_org_role
WHERE field_id = #{fieldId}

SELECT COUNT(1)
FROM sys_org_role_auth
WHERE field_auth_id = #{authId} AND field_role_id = #{roleId}

SELECT COUNT(1)
FROM sys_org_role_element
WHERE field_element_id = #{elementId} AND field_role_id = #{roleId}

SELECT COUNT(*)
FROM sys_org_role

    AND field_id = #{model.fieldId}
